Here is the commit message:
KVM: x86: check for nEPT/nNPT in slow flush hypercalls

Checking is_guest_mode(vcpu) is incorrect, because translate_nested_gpa()
is only valid if an L2 guest is running *with nested EPT/NPT enabled*.
Instead use the same condition as translate_nested_gpa() itself.

Cc: stable@vger.kernel.org
Reviewed-by: Sean Christopherson <seanjc@google.com>
Fixes: aee738236dca ("KVM: x86: Prepare kvm_hv_flush_tlb() to handle L2's GPAs", 2022-11-18)
Link: https://patch.msgid.link/20260503200905.106077-1-pbonzini@redhat.com/
Signed-off-by: Paolo Bonzini <pbonzini@redhat.com>

Here is the root cause:
The bug is caused by using `is_guest_mode(vcpu)` to decide whether to call `translate_nested_gpa()` in the slow flush hypercall path. `is_guest_mode()` is true whenever an L2 guest is running, but `translate_nested_gpa()` is only valid when nested EPT/NPT is enabled (i.e., when the nested MMU is active). Using the wrong condition can lead to invalid GPA translation or incorrect hypercall behavior when L2 is running without nested paging (e.g., with shadow paging).

Here is the patch:

 static u64 kvm_hv_flush_tlb(struct kvm_vcpu *vcpu, struct kvm_hv_hcall *hc)
 {
 	struct kvm_vcpu_hv *hv_vcpu = to_hv_vcpu(vcpu);
 	unsigned long *vcpu_mask = hv_vcpu->vcpu_mask;
 	u64 *sparse_banks = hv_vcpu->sparse_banks;
 	struct kvm *kvm = vcpu->kvm;
 	struct hv_tlb_flush_ex flush_ex;
 	struct hv_tlb_flush flush;
 	struct kvm_vcpu_hv_tlb_flush_fifo *tlb_flush_fifo;
 	/*
 	 * Normally, there can be no more than 'KVM_HV_TLB_FLUSH_FIFO_SIZE'
 	 * entries on the TLB flush fifo. The last entry, however, needs to be
 	 * always left free for 'flush all' entry which gets placed when
 	 * there is not enough space to put all the requested entries.
 	 */
 	u64 __tlb_flush_entries[KVM_HV_TLB_FLUSH_FIFO_SIZE - 1];
 	u64 *tlb_flush_entries;
 	u64 valid_bank_mask;
 	struct kvm_vcpu *v;
 	unsigned long i;
 	bool all_cpus;

 	/*
 	 * The Hyper-V TLFS doesn't allow more than HV_MAX_SPARSE_VCPU_BANKS
 	 * sparse banks. Fail the build if KVM's max allowed number of
 	 * vCPUs (>4096) exceeds this limit.
 	 */
 	BUILD_BUG_ON(KVM_HV_MAX_SPARSE_VCPU_SET_BITS > HV_MAX_SPARSE_VCPU_BANKS);

 	/*
 	 * 'Slow' hypercall's first parameter is the address in guest's memory
 	 * where hypercall parameters are placed. This is either a GPA or a
 	 * nested GPA when KVM is handling the call from L2 ('direct' TLB
 	 * flush).  Translate the address here so the memory can be uniformly
 	 * read with kvm_read_guest().
 	 */
-	if (!hc->fast && is_guest_mode(vcpu)) {
+	if (!hc->fast && mmu_is_nested(vcpu)) {
 		hc->ingpa = translate_nested_gpa(vcpu, hc->ingpa, 0, NULL);
 		if (unlikely(hc->ingpa == INVALID_GPA))
 			return HV_STATUS_INVALID_HYPERCALL_INPUT;
 	}

 	if (hc->code == HVCALL_FLUSH_VIRTUAL_ADDRESS_LIST ||
 	    hc->code == HVCALL_FLUSH_VIRTUAL_ADDRESS_SPACE) {
 		if (hc->fast) {
 			flush.address_space = hc->ingpa;
 			flush.flags = hc->outgpa;
 			flush.processor_mask = sse128_lo(hc->xmm[0]);
 			hc->consumed_xmm_halves = 1;
 		} else {
 			if (unlikely(kvm_read_guest(kvm, hc->ingpa,
 						    &flush, sizeof(flush))))
 				return HV_STATUS_INVALID_HYPERCALL_INPUT;
 			hc->data_offset = sizeof(flush);
 		}

 		trace_kvm_hv_flush_tlb(flush.processor_mask,
 				       flush.address_space, flush.flags,
 				       is_guest_mode(vcpu));

 		valid_bank_mask = BIT_ULL(0);
 		sparse_banks[0] = flush.processor_mask;

 		/*
 		 * Work around possible WS2012 bug: it sends hypercalls
 		 * with processor_mask = 0x0 and HV_FLUSH_ALL_PROCESSORS clear,
 		 * while also expecting us to flush something and crashing if
 		 * we don't. Let's treat processor_mask == 0 same as
 		 * HV_FLUSH_ALL_PROCESSORS.
 		 */
 		all_cpus = (flush.flags & HV_FLUSH_ALL_PROCESSORS) ||
 			flush.processor_mask == 0;
 	} else {
 		if (hc->fast) {
 			flush_ex.address_space = hc->ingpa;
 			flush_ex.flags = hc->outgpa;
 			memcpy(&flush_ex.hv_vp_set,
 			       &hc->xmm[0], sizeof(hc->xmm[0]));
 			hc->consumed_xmm_halves = 2;
 		} else {
 			if (unlikely(kvm_read_guest(kvm, hc->ingpa, &flush_ex,
 						    sizeof(flush_ex))))
 				return HV_STATUS_INVALID_HYPERCALL_INPUT;
 			hc->data_offset = sizeof(flush_ex);
 		}

 		trace_kvm_hv_flush_tlb_ex(flush_ex.hv_vp_set.valid_bank_mask,
 					  flush_ex.hv_vp_set.format,
 					  flush_ex.address_space,
 					  flush_ex.flags, is_guest_mode(vcpu));

 		valid_bank_mask = flush_ex.hv_vp_set.valid_bank_mask;
 		all_cpus = flush_ex.hv_vp_set.format !=
 			HV_GENERIC_SET_SPARSE_4K;

 		if (hc->var_cnt != hweight64(valid_bank_mask))
 			return HV_STATUS_INVALID_HYPERCALL_INPUT;

 		if (!all_cpus) {
 			if (!hc->var_cnt)
 				goto ret_success;

 			if (kvm_get_sparse_vp_set(kvm, hc, sparse_banks))
 				return HV_STATUS_INVALID_HYPERCALL_INPUT;
 		}

 		/*
 		 * Hyper-V TLFS doesn't explicitly forbid non-empty sparse vCPU
 		 * banks (and, thus, non-zero 'var_cnt') for the 'all vCPUs'
 		 * case (HV_GENERIC_SET_ALL).  Always adjust data_offset and
 		 * consumed_xmm_halves to make sure TLB flush entries are read
 		 * from the correct offset.
 		 */
 		if (hc->fast)
 			hc->consumed_xmm_halves += hc->var_cnt;
 		else
 			hc->data_offset += hc->var_cnt * sizeof(sparse_banks[0]);
 	}

 	if (hc->code == HVCALL_FLUSH_VIRTUAL_ADDRESS_SPACE ||
 	    hc->code == HVCALL_FLUSH_VIRTUAL_ADDRESS_SPACE_EX ||
 	    hc->rep_cnt > ARRAY_SIZE(__tlb_flush_entries)) {
 		tlb_flush_entries = NULL;
 	} else {
 		if (kvm_hv_get_tlb_flush_entries(kvm, hc, __tlb_flush_entries))
 			return HV_STATUS_INVALID_HYPERCALL_INPUT;
 		tlb_flush_entries = __tlb_flush_entries;
 	}

 	/*
 	 * vcpu->arch.cr3 may not be up-to-date for running vCPUs so we can't
 	 * analyze it here, flush TLB regardless of the specified address space.
 	 */
 	if (all_cpus && !is_guest_mode(vcpu)) {
 		kvm_for_each_vcpu(i, v, kvm) {
 			tlb_flush_fifo = kvm_hv_get_tlb_flush_fifo(v, false);
 			hv_tlb_flush_enqueue(v, tlb_flush_fifo,
 					     tlb_flush_entries, hc->rep_cnt);
 		}

 		kvm_make_all_cpus_request(kvm, KVM_REQ_HV_TLB_FLUSH);
 	} else if (!is_guest_mode(vcpu)) {
 		sparse_set_to_vcpu_mask(kvm, sparse_banks, valid_bank_mask, vcpu_mask);

 		for_each_set_bit(i, vcpu_mask, KVM_MAX_VCPUS) {
 			v = kvm_get_vcpu(kvm, i);
 			if (!v)
 				continue;
 			tlb_flush_fifo = kvm_hv_get_tlb_flush_fifo(v, false);
 			hv_tlb_flush_enqueue(v, tlb_flush_fifo,
 					     tlb_flush_entries, hc->rep_cnt);
 		}

 		kvm_make_vcpus_request_mask(kvm, KVM_REQ_HV_TLB_FLUSH, vcpu_mask);
 	} else {
 		struct kvm_vcpu_hv *hv_v;

 		bitmap_zero(vcpu_mask, KVM_MAX_VCPUS);

 		kvm_for_each_vcpu(i, v, kvm) {
 			hv_v = to_hv_vcpu(v);

 			/*
 			 * The following check races with nested vCPUs entering/exiting
 			 * and/or migrating between L1's vCPUs, however the only case when
 			 * KVM *must* flush the TLB is when the target L2 vCPU keeps
 			 * running on the same L1 vCPU from the moment of the request until
 			 * kvm_hv_flush_tlb() returns. TLB is fully flushed in all other
 			 * cases, e.g. when the target L2 vCPU migrates to a different L1
 			 * vCPU or when the corresponding L1 vCPU temporary switches to a
 			 * different L2 vCPU while the request is being processed.
 			 */
 			if (!hv_v || hv_v->nested.vm_id != hv_vcpu->nested.vm_id)
 				continue;

 			if (!all_cpus &&
 			    !hv_is_vp_in_sparse_set(hv_v->nested.vp_id, valid_bank_mask,
 						    sparse_banks))
 				continue;

 			__set_bit(i, vcpu_mask);
 			tlb_flush_fifo = kvm_hv_get_tlb_flush_fifo(v, true);
 			hv_tlb_flush_enqueue(v, tlb_flush_fifo,
 					     tlb_flush_entries, hc->rep_cnt);
 		}

 		kvm_make_vcpus_request_mask(kvm, KVM_REQ_HV_TLB_FLUSH, vcpu_mask);
 	}

 ret_success:
 	/* We always do full TLB flush, set 'Reps completed' = 'Rep Count' */
 	return (u64)HV_STATUS_SUCCESS |
 		((u64)hc->rep_cnt << HV_HYPERCALL_REP_COMP_OFFSET);
 }



